      "Տոլման կը ճանչցուի պատրաստելու ձեւէն, ոչ թէ բաղադրիչներու հաստատուն ցանկէ մը։ Բրինձը, սոխն ու առատ կանաչեղէնը, աղացած գառնուկի կամ արջառի միսով կամ առանց միսի, կը փաթթեն որթատունկի կամ կաղամբի տերեւի մէջ, կամ կը լեցնեն պարպուած պղպեղի, սմբուկի, լոլիկի ու սերկեւիլի մէջ։ Ապա ծրարները խիտ կը շարեն կաթսային մէջ, վրան ծանրութիւն կը դնեն ու կամաց կ՚եփեն։ Անունը կու գայ «լեցուիլ» նշանակող թիւրքական բայէ մը։ Անմիս տարբերակը՝ պասուց տոլման, կը պատրաստուի լուբիայով, սիսեռով, ոսպով ու հատիկեղէնով, կը մատուցուի պաղ եւ պահքի օրերու կերակուր է։ Հայ տուներուն մէջ տոլման հաւաքոյթներու կերակուր է, ոչ թէ առօրեայ ճաշ, եւ հարիւրաւոր տերեւ փաթթելը հաւաքական աշխատանք է։ Ձեւը հին է եւ ամբողջ տարածաշրջանին մէջ տարածուած՝ ազգակից անուններով։ ԵՈՒՆԵՍՔՕ-ի 2017-ի ընդգրկումը Ազրպէյճանի ներկայացումով եղած է, եւ կենդանի աւանդութիւն մը կ՚արձանագրէ, ոչ թէ ծագում մը։",
    intro:
      "Տոլման բրինձէ, սոխէ, կանաչեղէնէ եւ յաճախ աղացած միսէ լեցոն մըն է, որ տերեւներու մէջ կը փաթթուի կամ պարպուած բանջարեղէնի մէջ կը լեցուի եւ կամաց կ՚եփուի։ Զայն կը պատրաստեն ամբողջ Կովկասի, Անատոլիոյ, Իրանի եւ Արեւելեան Միջերկրականի մէջ, նոյն բայէն ծագած անուններով։ Հայ տուներուն մէջ ան հաւաքոյթներու կերակուր է, ոչ թէ առօրեայ արագ ճաշ, եւ պահքի համար անմիս տարբերակ մըն ալ ունի։ 2017-ին ԵՈՒՆԵՍՔՕ իր ներկայացուցչական ցանկին մէջ առաւ տոլմա պատրաստելու աւանդութիւնը։ Այդ ընդգրկումը Ազրպէյճանի ներկայացումով եղած է։ Այս յօդուածը ատիկա չի շրջանցեր, որովհետեւ ընդգրկումին մեկնաբանութիւնն ալ տոլմային պատմութեան մաս կը կազմէ։",
