    summary:
      "Հարիսան կը պատրաստեն մաքրուած ցորենէ, որ հայերէն կորկոտ կը կոչուի, եւ հաւու կամ գառնուկի միսէ։ Զանոնք ժամերով կ՚եփեն ու կը խառնեն, մինչեւ որ միսը ամբողջովին քանդուի, ցորենը բացուի, եւ կերակուրը դառնայ մէկ թանձր զանգուած, ոչ թէ կտորներով ապուր։ Խտութիւնն է անոր չափանիշը. լաւ պատրաստուած հարիսան մէկ կտորով կը զատուի դգալէն։ Մատուցելէ առաջ վրան հալած կարագ կը լեցնեն, իսկ քիմիոնն ու պղպեղը առանձին կը դնեն։ Շատ քիչ բանով շատ մարդ կը կշտացնէ, ուստի աւելի հաւաքական ու եկեղեցական առիթներու կերակուր է, քան ընտանեկան սեղանի։ Անոր գրաւոր պատմութիւնը կը հասնի Պաղտատի տասներորդ դարու խոհարարական գիրքի մը, եւ ազգակից անուններով տարբերակներ կը պատրաստուին ամբողջ Միջին Արեւելքի մէջ։ Իսկ անոր ամէնէն ծանօթ հայկական առիթը շատ աւելի նոր է. ամէն Սեպտեմբեր Արմաւիրի մարզի Մուսալեռ գիւղին մէջ կը յիշեն 1915-ի Մուսա լերան դիմադրութիւնը։",
    intro:
      "Հարիսան մաքրուած ցորենէ ու միսէ կը պատրաստուի։ Զանոնք միասին ժամերով կ՚եփեն ու կը խառնեն, մինչեւ որ մէկը միւսէն չզատուի։ Ան նուրբ կերակուր չէ եւ երբեք ալ այդպիսին ըլլալու համար չէ ստեղծուած. շատ քիչ բանով շատ մարդ կը կշտացնէ, եւ մեծ կաթսայի մը մէջ կրնայ ամբողջ գիշեր եփիլ։ Անոր գրաւոր պատմութիւնը կը հասնի Պաղտատի տասներորդ դարու խոհարարական գիրքի մը, ուր հարիսան կը յիշուի իբրեւ ծեծուած ցորենով ու միսով կերակուր։ Անոր ամէնէն ծանօթ հայկական առիթը շատ աւելի նոր է. ամէն Սեպտեմբեր Արմաւիրի մարզի Մուսալեռ գիւղին մէջ կը յիշեն 1915-ի Մուսա լերան դիմադրութիւնը։",
