      "Գաթան անուշ թխուածք է, որուն լեցոնը իր սեփական անունը ունի՝ խորիզ։ Խորիզը կակուղ կարագին ու շաքարին հետ շփուած ալիւր է, որ փշրանքի պէս կը մնայ եւ փուռին մէջ կը հալի ու խմորին կը միանայ։ Խմորը կարագով կը հարստացնեն, յաճախ ալ մածունով կամ թթուասերով։ Թխելէ առաջ երեսին ձու կը քսեն ու նախշ կը քաշեն. այս զարդարանքը նաեւ կ՚արգիլէ, որ երեսը ուռի։ Գաթան խոնաւ չէ, չոր է, ու ատոր համար երկար կը պահուի եւ ճամբու կը դիմանայ։ Ամբողջ, փաթթուած գաթա մը այցելութեան տարուող սովորական նուէրն է, իսկ վանքերու դռներուն քով ծախուող նախշուած շրջանները շատերու յիշողութեան մէջ գաթային իսկական դէմքն են։ Մնացեալը գրեթէ ամբողջովին կը փոխուի։ Գաթան կրնայ սեղանի մը չափ լայն ըլլալ կամ ափի մէջ տեղաւորուող գլանիկ մը։ Շատ ընտանիքներ իրենց սեփական նախշը ունին, իսկ ընկոյզով տարբերակը, որ կը պատրաստուի հարաւը եւ Իրանի հայերուն մօտ, յաճախ նազուկ կը կոչուի։",
    intro:
      "Գաթան անուշ խմորեղէն է, որուն լեցոնը իր սեփական անունը ունի՝ խորիզ։ Խորիզը կարագին ու շաքարին հետ շփուած ալիւր է, որ թխուելու ատեն կը հալի ու խմորին կը միանայ։ Ասկէ անդին գրեթէ ամէն բան կը փոխուի։ Գաթան կրնայ սեղանի մը չափ լայն շրջան ըլլալ կամ ափի մէջ տեղաւորուող գլանիկ, կրնայ պարզ ըլլալ կամ խիտ նախշուած։ Կրնայ տօնական խմորեղէն ըլլալ, այցելութեան տարուող նուէր, կամ ալ պարզապէս կէսօրէ ետք սուրճին ընկերացող բան մը։ 2018 թուականին գաթան Սմիթսոնեան ժողովրդական մշակոյթի փառատօնի հայկական ծրագրին մէջ ցուցադրուած անուշեղէններէն մէկն էր։",
