      "Խաշը արգանակ է. տաւարի տոտիկները պարզ ջուրի մէջ կ՚եփեն գիշերուան մեծ մասը, ապա ձմրան առաւօտուն կը մատուցեն եռացող ու անաղ։ Ամէն մարդ իր ամանը ինք կ՚աւարտէ՝ սխտորով, աղով եւ փշրուած չոր լաւաշով։ Ատոր համար ալ խաշը ափսէ մը չէ, սեղան մըն է։ Սովորութիւնը զայն կը կապէ ցուրտ ամիսներուն ու կանուխ ժամերուն, իսկ բոլոր աղբիւրները, ամէն բանէ առաջ, մէկ բանի մէջ համաձայն են. խաշը մինակ չեն ուտեր։ Անգլերէնի մէջ ամէնէն շատ կրկնուող երկու պնդումները՝ թէ խաշը շատ հին է ու չէ փոխուած, եւ թէ խումհարը կ՚անցընէ, ճիշդ այն երկուքն են, որոնց աղբիւրները ամէնէն քիչ հիմք կու տան։",
    intro:
      "Խաշը կը ծնի, երբ կենդանիին ամէնէն կարծր մասերուն բաւական ժամանակ տրուի։ Տաւարի տոտիկները կը մաքրեն, երկար ժամեր սառը ջուրի մէջ կը պահեն, ապա միայն ջուրով կ՚եփեն, մինչեւ որ անոնցմէ անջատուածը արգանակը թանձրացնէ եւ միսը ոսկորէն բաժնուի։ Գիշերուան մեծ մասը կ՚երթայ լուսաբացին ուտուելիք կերակուրի մը վրայ։ Խաշը սեղան կու գայ եռացող ու անհամեմ, եւ սեղանակիցներէն իւրաքանչիւրը իր ամանը ինք կ՚աւարտէ՝ սխտորով, աղով ու փշրուած չոր հացով։ Ուտելիքը այսքան պարզ է։ Եղանակը, ժամը, կենացներն ու ընկերակցութիւնը անոր շուրջ հիւսուած սովորութիւնն են, եւ այս յօդուածը մեծաւ մասամբ այդ սովորութեան մասին է։",
