          "Պատճառը ուրիշ հարց է, եւ պէտք է յստակ ըսել, որ գործածուած աղբիւրներէն ոչ մէկը զայն կը հաստատէ։ Ամէնէն շօշափելի բացատրութիւնը պարզապէս մեքենական է. գիշերուան մեծ մասը եփուող կերակուրը առաւօտուն պատրաստ կ՚ըլլայ։ Պենճամին Քեմփըր, Սմիթսոնեանի ժողովրդական մշակոյթի ծրագրին համար խաշը նկարագրելով, կը նշէ, որ ժամը իննին սկսող հաւաքի մը համար խոհարարը պարտաւոր է գիշերով գործի սկսիլ։ Նոյն տրամաբանութիւնը ինքնուրոյն կերպով կը տեսնենք Իրանի մէջ, ուր ազգակից կերակուրը նոյնպէս առաւօտուն կ՚ուտուի ու գիշերով կ՚եփուի։",
          "Կը պտտին ուրիշ բացատրութիւններ ալ. թէ կերակուրը օրուան ուշ ժամերուն համար չափազանց ծանր է, թէ ցուրտ առաւօտը կը տաքցնէ, թէ կերուխումով անցած երեկոյին յաջորդող առաւօտուն կը պատկանի։ Ամէնքն ալ հաւանական են, բայց ոչ մէկը վաւերագրուած է իբրեւ պատճառ։ Ճշմարտութիւնը այն է, որ սովորութիւնը հաստատ է, իսկ ծագումը՝ ոչ։ Եթէ յօդուածը հոս վստահ պատճառ մը ներկայացնէր, զայն պիտի հնարէր։",
