          "Քանի որ կաթսան համեմել կարելի չէ, համեմելը սեղանին կը մնայ։ Սեղանին շուրջ կը դառնայ սխտորը՝ ծեծուած, յաճախ աղով տրորուած կամ քիչ մը տաք արգանակով նօսրացուած, անոր հետ ալ՝ աղը, բողկը, թարմ կանաչին ու թթուն։ Ամէն մարդ իր ամանը իր ճաշակով կը համեմէ, եւ քանակը ինք կ՚որոշէ։ Ասիկա խաշին հիմնական առանձնայատկութիւնն է, որ լուսանկարները երբեք լիովին չեն փոխանցեր. կերակուրը ափսէ չէ, սեղան է։ Ամէն մարդ զայն ոչ միայն կ՚ուտէ, այլ նաեւ ինք կ՚ամբողջացնէ։",
          "Լաւաշը այս սեղանին վրայ երկու գործ կը կատարէ, ատոր համար ալ անոր տեղը հոս է, եւ ոչ թէ կողմնակի ուտելիքներու ցանկին մէջ։ Չոր լաւաշը արգանակին մէջ կը փշրեն, մինչեւ որ հեղուկը թանձրանայ ու շիլայի նմանի, իսկ փափուկ լաւաշով կ՚առնեն ու կը փաթթեն։ Կարգ մը վկայութիւններ կը յիշեն նաեւ ամանին վրայ դրուած թերթ մը, որ տաքութիւնը պահէ։ Չոր լաւաշ կայ, որովհետեւ լաւաշը ամիսներով կը պահուի եւ քիչ մը ջուր ցանելով նորէն կը փափկի. հացին այս յատկութիւնը կը նկարագրէ ԻՒՆԵՍՔՕ-ի արձանագրութիւնը։ Ահա թէ ինչու ձմեռային կերակուրը ձեռքի տակ ունի հաց մը, որ բաղադրիչի պէս կը գործէ։",
          "Սխտորը համեստ չէ։ Վկայութիւն մը կը խօսի ամէն ամանի համար մինչեւ ութ պճեղի մասին, բայց ասիկա պէտք է կարդալ իբրեւ դիտողութիւն, ոչ թէ կանոն։ Հոս պէտք է զատել լայնօրէն վկայուածը եզակիէն։ Սխտորը, աղը, լաւաշը, բողկը, կանաչին ու թթուն կը կրկնուին թէ՛ հայերէն մամուլին, թէ՛ հաստատութիւններու գրութիւններուն մէջ, մինչդեռ կիտրոնն ու քացախը արդի բաղադրատոմսի մը կը պատկանին։ Մէկ ճաշարանի սեղանը համազգային սովորութիւն չէ, եւ այս յօդուածը կը գրուի ճիշդ այսպիսի տարբերութիւններ նշելու համար։",
