        paragraphs: [
          "Այս յօդուածին համար գործածուած բոլոր աղբիւրները, ամէն բանէ առաջ, մէկ կէտի մէջ համաձայն են։ Ռաֆիք Նահապետեան 2019 թուականին Պատմաբանասիրական հանդէսին մէջ ուսումնասիրած է հայոց սննդային համակարգը եւ ատիկա կը ներկայացնէ իբրեւ պարզ ազգագրական իրողութիւն. խաշը մեր օրերուն ալ, առաջուան պէս, գրեթէ երբեք առանց հիւրի չեն ուտեր։ Հետքի հետ զրուցած խոհարարներէն մէկը նոյն բանը կ՚ըսէ առօրեայ բառերով. խաշի համար չեն հաւաքուիր կշտանալու համար, ատոր համար աւելուկով ապուրն ալ բաւ է. կը հաւաքուին, որ միասին սեղան նստին։",
          "Հաւաքը իր սովորական կարգը ունի։ Հետքը կ՚արձանագրէ երեք կենաց՝ հերթով. նախ ողջոյնի կենացը, ապա եփողին կենացը, ապա մաղթանք մը, որ խաշը բարի ըլլայ։ Քեմփըր կարգը այլ կերպ կու տայ՝ օրուան, խոհարարներուն ու հիւրերուն կենացները, իսկ Հետքի խոհարարներէն մէկը կ՚առարկէ, թէ թիւ ճշդելը արդէն իմաստը կը կորսնցնէ։ Կարգ մը արդի նկարագրութիւններ օղին կամ մրգային օղին կը նկատեն չափահասներու այս հաւաքներուն մէկ մասը։ Այս յօդուածը ատիկա կ՚արձանագրէ միայն իբրեւ վաւերագրուած սովորութիւն. ան ո՛չ կերակուրին կողմէ կը պահանջուի, ո՛չ ալ հոս խորհուրդ կը տրուի։ Հաւաքը նաեւ յստակ սեռային բնոյթ ունեցած է. պատմականօրէն ան այրերու առիթ էր։ Ազգագրագէտ Ռուզաննա Ցատուրեան կը նկարագրէ, որ կիներու խաշի հաւաքները իր խօսքէն տասը տարի առաջ դժուար երեւակայելի էին, իսկ այժմ սովորական են։",
          "Սեղանին իմաստը փոխուած է անոր շրջապատին հետ։ Մշակութաբան Հրաչ Բայադեան, դարձեալ Հետքի հետ զրոյցի մը մէջ, կը պատմէ, թէ ինչպէս խորհրդային տարիներու մտաւորականներուն մէջ խաշը լուռ երանգ մը ստացաւ։ Ան առիթ մըն էր պետութեան կազմակերպած հանրային առիթներու օրացոյցէն դուրս, առաւօտ մը, որ դիտմամբ աշխատանքի չէր տրուեր, եւ այդ իմաստով՝ մերժումի մեղմ ձեւ մը։ Խաշին ամէնէն կապուած քաղաքը նոյն բանը կ՚ըսէ ուրիշ կողմէ։ Կիւմրին կը պնդէ, թէ խաշը Հայաստանի որեւէ ուրիշ տեղէ աւելի կը սիրէ, եւ Մամուլեան կը վկայէ, որ հարսանիքէն ետք առաւօտուն խաշ ուտելու սովորութիւնը մասնաւորապէս հոն պահպանուած է։",
        ],
        links: [{ phrase: "Կիւմրին", slug: "gyumri" }],
