      "Մածունը կաթ է, որ կաթնաթթուային մանրէները կը թթուեցնեն, մինչեւ որ մակարդուի ու դառնայ թանձր, թթու, դգալով ուտուող մթերք։ Զայն կ՚ուտեն առանձին ու հացով, բայց ան նաեւ խոհանոցին հիմքն է. ջուրով նօսրացնելով՝ ըմպելիք կը դառնայ, եփելով՝ ապուր, քամելով ու աղելով՝ պահեստի ուտելիք, իսկ չորցնելով՝ կարծր ու թթու գնդիկներ, որոնք տարիներով կը դիմանան։ Մէկ ամանէն պահուած քիչ մը մածուն կը սկսի յաջորդը, ատոր համար ալ աւանդական մածունը տեղական մանրէներու համայնք մը կը կրէ, ոչ թէ գնուած մերան։ Հայկական ու վրացական աւանդութիւնները նոյն մթերքն են՝ երկու անունով, եւ երկու երկիրներու մանրէաբանները զանոնք միասին ուսումնասիրած են։ Բառը բնիկ հայերէն է ու հին. իսկ թէ մթերքը իր այսօրուան ձեւով որքա՛ն հին է, առանձին հարց է, որուն աղբիւրները պատասխան չեն տար։",
