      "Մածունը կ՚ըլլայ, երբ կաթին վրայ ճիշդ մանրէները գործեն։ Անոնք կաթին շաքարը թթուի կը վերածեն, թթուն սպիտակուցը կը խախտէ, եւ ամբողջ ամանը կը մակարդուի՝ դառնալով թանձր, թթու ու դգալով ուտուող բան մը, որ կաթէն շատ աւելի երկար կը պահուի։ Ամբողջ փոխակերպումը այսքան է։ Հայկական տուները շատ երկար ժամանակէ ի վեր զայն անընդհատ կը կրկնեն ամէնէն պարզ ձեւով. երէկուան մածունէն դգալ մը կը պահեն, որ վաղուանը սկսին։ Ասիկա այս բաժինին առաջին յօդուածն է, որ պատրաստ կերակուրի մը մասին չէ, այլ հիմնական մթերքի մը։ Մածունը առանձին կ՚ուտուի, բայց հայկական խոհանոցին զգալի մասն ալ անկէ կը պատրաստուի։",
