          "Բաստուրման այս կամ այն ձեւով կը պատկանի հայկական, թրքական, յունական, արաբական, քրտական, պուլկարական, եգիպտական եւ ազրպէյճանական խոհանոցներուն, եւ անոր տարբերակները կը պատրաստուին անոնց բոլորին մէջ։ Ցանցին սիրած հարցը՝ «ո՞վ հնարեց», վկայութիւններով հաստատուող պատասխան չունի, եւ այդ խորագրին տակ ծաւալած վէճերը գրեթէ միշտ ուտելիքէն տարբեր բանի մը մասին են։ Այս յօդուածը այդ հարցին մէջ դիրք չի բռներ, որովհետեւ դիրք բռնելու համար պէտք պիտի ըլլային աղբիւրներ, որոնք գոյութիւն չունին։",
          "Այն հարցերը, որոնց կարելի է պատասխանել, աւելի նեղ են, բայց աւելի լաւ։ Հայերը աղուած ու չորցուած միսի համար բնիկ բառ մը ունին, որ վկայուած է հինգերորդ դարուն եւ անցած է երկու ուրիշ լեզուի։ Հայերը այս արհեստով ամէնէն հռչակաւոր քաղաքին մէջ առեւտուրին փաստագրուած մասնագէտներն էին։ Հայերը 1915-էն ետք արհեստը Անատոլիայէն դուրս բերին ու պահեցին կէս տասնեակ երկիրներու մէջ. ահա թէ ինչո՛ւ Լոս Անճելըսի խանութ մը կրնայ իր գործին ակունքը Լիբանանի ճամբով հասցնել Հայաստան։ Ասիկա իւրայատուկ ու լաւ վկայուած հայկական աւանդութիւն մըն է՝ ընդհանուր շրջանային պատմութեան մը ներսը, եւ ծանրակշիռ ըլլալու համար գիւտի պնդումի պէտք չունի։",
          "Երկու դրացի ուտելիք արժէ յիշել, որպէսզի այս մէկին սահմանները յստակ գծուին։ Սուճուխը՝ չոր ու համեմուած երշիկը, որ հայկական նախաճաշի ամէն նկարագրութեան մէջ բաստուրմային կողքին կը կենայ, տարբեր եղանակ է. միսը կ՚աղացուի ու թաղանթի մէջ կը լեցուի, ոչ թէ ամբողջական կը պահուի։ Սուճուխը հոս տակաւին իր յօդուածը չունի։ Իսկ փասթրամին լեզուական ազգական մըն է, ոչ թէ սերունդ։ Թրքերէն բառը ռումաներէնին անցաւ pastramă ձեւով եւ տասնիններորդ դարու վերջերուն ռումանահրեայ գաղթականներուն հետ հասաւ Նիւ Եորք, ուր ուտելիքը ինքնին վերաշինուեցաւ կուրծքի միսի, աղաջուրի ու ծուխի շուրջ։ Բաստուրման փասթրամի չդարձաւ։ Երկուքին նախահայրը «սեղմել» նշանակող բառ մըն է, որմէ ետք անոնք իրարմէ բաժնուեցան։",
