          "Ասիկա նաեւ այն կէտն է, ուր անգլիալեզու աղբիւրները չափը կ՚անցնեն, եւ արժէ ատիկա ըսել, որովհետեւ ամէն տեղ կը կրկնուի։ Կ՚ըսուի, թէ հայկական մանթին միշտ կը թխուի եւ երբեք ջուրի մէջ կամ շոգիով չ՚եփուիր՝ ի տարբերութիւն շրջանի միւս բոլոր տարբերակներուն։ Ասիկա վկայութիւններէն աւելի ուժեղ պնդում է, եւ հայկական սովորութիւնն իսկ կը հերքէ զայն։ Սուլու մանթին՝ ապուրով մանթին (թրքերէն սու՝ «ջուր» բառէն), հայկական է. անոր խմորագունդերը փակ են ու չեն թխուիր, այլ արգանակի մէջ կ՚եփուին։ Հայաստանի հայալեզու խոհանոցային կայքերն ալ սովորաբար կու տան բազմայարկ շոգեփիչի մէջ եփուող մանթի՝ աւելի մեծ, կեդրոնասիական ձեւով։",
          "Ազնիւ ձեւակերպումը աւելի նեղ է, բայց կը դիմանայ վկայութիւններուն։ Թխուած բաց ձեւը բնորոշ ու լայնօրէն փաստագրուած հայկական ոճ մըն է, սերտօրէն կապուած արեւմտահայ խոհանոցին, եւ մարդոց մեծ մասը «հայկական մանթի» ըսելով ճիշդ զայն կը հասկնայ։ Բայց ան կանոն մը չէ, որուն կը հետեւի ամէն հայկական խոհանոց, եւ անկէ տարբեր տարբերակները սխալ չեն։ Այս յօդուածը ձեւ մը կը նկարագրէ եւ ոչ թէ սահման մը։",
