          "Մածունը նոյն կերպով ընտրովի չէ։ Սխտորի հետ ծեծուած մածունը կ՚երթայ ամէնէն վրան, եւ ուտելիքին ամբողջ իմաստը տաք թխուած խմորին, տաք արգանակին ու պաղ, թթու մածունին միացումն է։ Մածունը հայկական թթուեցուցած կաթն է, որուն նուիրուած է այս բաժինին առանձին յօդուածը, եւ արժէ զայն իր անունով կոչել։ Անգլիախօս խոհանոցներու համար գրուած խոհարարական էջերը սովորաբար յունական եոկուրտ կամ լապնէ կ՚առաջարկեն. անոնք տրամաբանական փոխարինողներ են, բայց նոյն մթերքը չեն։ Ուտելիքը կը պատկանի խոհանոցի մը, որ մածուն ունէր մանթիէն շատ առաջ։",
