          "Ազնիւ ամփոփումը սա է. մանթիներու լայն ընտանիքը ունի շրջաններէ անդին երկարող պատմութիւն մը, զոր ոչ մէկ ժողովուրդ առանձին հնարած է, եւ հայկական թխուած ձեւը այդ ընտանիքին ներսը առանձին զարգացում մըն է։ Այս նախադասութեան երկու կէսերն ալ պէտք են։ Առաջինը դուրս ձգելով՝ կը ծնին հնարումի այն պնդումները, որոնք միաժամանակ քանի մը լեզուով կը շրջին։ Երկրորդը դուրս ձգելով՝ յստակ ու լաւ վկայուած խոհարարական սովորութիւն մը կը վերածուի պարզ փոխառութեան, ինչ որ ան չէ։",
