        "Մանթին բաժինին ամէնէն յստակ օրինակն է նաեւ, ուր ընդհանուր ուտելիք մը իւրայատուկ կը դառնայ պատրաստութեան ձեւով, ոչ թէ բաղադրիչներով։ Մանթիին մէջ ինքնին հայկական ոչինչ կայ. խմորը ցորեն ու ջուր է, լեցոնը՝ աղացած գառան միս, անունը՝ արեւելքէն եկած։ Հայկականը այն որոշումն է, որ ծրարը բաց ձգուի ու փուռ դրուի, ապա փուռէն ելածին վրայ արգանակ ու սխտորով մածուն լեցուի։ Այս պզտիկ խոհանոցային տարբերութիւնը բոլորովին ուրիշ ուտելիք մը կը ծնի։ Զայն արժէ պաշտպանել որեւէ ծագման պնդումի չափ խնամքով, նոյնիսկ աւելի, որովհետեւ, ի տարբերութիւն ծագման պնդումներուն, զայն իսկապէս կարելի է ցոյց տալ։",
